// Anti-aliased step
float aastep(float a, float x) {
    float fw = 0.75*length(vec2(dFdx(x-a), dFdy(x-a)));
    return smoothstep(-fw, fw, x-a);
}

// Anti-aliased line of width w pixels around position x=a
// (This abs() version doesn't do well with w < 1.0)
float aaline(float a, float x, float w) {
    // Use an isotropic replacement for fwidth()
    float fw = 0.5*length(vec2(dFdx(x-a), dFdy(x-a)));
    return 1.0-smoothstep((w-1.5)*fw, (w+1.5)*fw, abs(x-a));
}

//
// This is a rough approximation to trochoid "Gerstner waves",
// made specifically to be easy to invert. The formal numeric
// accuracy is terrible, but the general likeness is quite good,
// the overall dynamic behavior is convincing, and the code is
// simple.
// By Stefan Gustavson 2025-01-19, released under the CC license
// CC-BY-SA-4.0 (https://creativecommons.org/licenses/by-sa/4.0/)
// ("Use freely for any purpose, but give credit and share modifications.")
//
float fakegerstner(float x, float b, out float warp, out float dfdx) {
    x = mod(x+0.5,2.0)-0.5; // Valid range for cos approximation is [-0.5,0.5]
    float flip = (x > 0.5) ? -1.0 : 1.0; // Remember sign flip for animation below
    x = (flip >= 0.0) ? x: 1.0-x; // Mirror up-slope to compute down-slope
    const float PI = 3.1415926536;
    // We scale x by 1/pi and fake a cos(), so our range for b is [0,1/4]
    float bm = b*0.25;
    float A = sqrt(16.0*bm*(bm-x)+1.0); // This sub-expression is re-used 3x
    float ibm8 = 0.125/bm; // 1/(8*bm), used twice, this saves one division
    float x0 = (1.0-A)*ibm8;
    warp = flip*(x0-x);
    float f = 8.0/PI*b*sin(x0*PI);
    dfdx = flip*8.0*bm*cos(PI*(A-1.0)*ibm8)/A; // Flip the sign at down-slope
    return f;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Coordinates are -1 to 1 in x
    vec2 uv;
    float b, bm, x, x0, dx, y, dydx, t;

    uv = 4.0*fragCoord/max(iResolution.x, iResolution.y);
    uv.x -= 2.0;
    uv.y = (uv.y-0.5);

    if((iMouse.y == 0.0) && (iMouse.x == 0.0)) // If mouse was never touched
        b = 0.9;
    else
        b = min(iMouse.y/iResolution.y, 1.0); // Prevent overflow after fullscreen

    t = iTime;

    // Animate the wave at 0.5 Hz (Wavelength is 2.0)
    x = uv.x - t;

    y = fakegerstner(x, b, dx, dydx);

    x0 = x + dx;

    // Plot the wave profile as a function y=f(x)
    float yline = aaline(y*0.1, uv.y, 6.0);
    // Show the contraction and expansion in x.
    // This is required to animate the texture coordinates correctly.
    // Features and objects on water waves bob around sideways as well!
    float dashx = abs(mod(x0 + t, 0.1)-0.05); // Note: x0, not x
    float dash = aastep(0.025, dashx);
    float markx = abs(mod(x0 + t, 1.0)); // Mark one dash
    float mark = aastep(0.475, markx) - aastep(0.525, markx);

    // Just a 2-D curve plot, to show the principle
    vec3 ylinecol = mix(vec3(1.0), vec3(0.0), dash);
    ylinecol = mix(ylinecol, vec3(0.9,0.0,0.0), mark);
    vec3 bgcol = vec3(0.2, 0.2, 0.8);

    // Draw circles to mark the motion path of two surface points
    float orbit1 = aaline(0.25*b, distance(uv, vec2(-0.5,0.0)), 3.0);
    float orbit2 = aaline(0.25*b, distance(uv, vec2(0.5,0.0)), 3.0);
    vec3 orbitcol = vec3(1.0,1.0,0.0);
    vec3 col = mix(bgcol, orbitcol, max(orbit1, orbit2));
    // Rotating tick marks showing the correct paths.
    // The approximation remains reasonably close throughout.
    const float PI = 3.1415926536;
    float Cphi = 0.25*b*cos(t*PI);
    float Sphi = 0.25*b*sin(t*PI);
    float tick1 = 1.0-aastep(0.07, distance(uv, vec2(-0.5-Sphi, -Cphi)));
    float tick2 = 1.0-aastep(0.07, distance(uv, vec2(0.5+Sphi, Cphi)));
    col = mix(col, orbitcol, max(tick1, tick2));
    col = mix(col, ylinecol, yline);

    fragColor = vec4(col,1.0);
}
